26:         constexpr uintptr_t POSITION_Y = 0x14;                  // float y coordinate
27:         constexpr uintptr_t CLASS_TYPE = 0x20;                  // int class (0-6)
28:         constexpr uintptr_t LEVEL = 0x24;                       // int level (1-99)
