PlayerState BotEngine::GetPlayerState() const
{
    PlayerState state = {};
    if (!m_processHandle)
        return state;

    try {
        MemoryReader reader(m_processHandle);

        // Get D2R module base
        MODULEENTRY32 me32 = { sizeof(MODULEENTRY32) };
        HANDLE hModuleSnap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE, m_processId);
        if (hModuleSnap != INVALID_HANDLE_VALUE) {
            uintptr_t moduleBase = 0;

            if (Module32First(hModuleSnap, &me32)) {
                do {
                    if (_wcsicmp(me32.szModule, L"D2R.exe") == 0) {
                        moduleBase = (uintptr_t)me32.modBaseAddr;
                        break;
                    }
                } while (Module32Next(hModuleSnap, &me32));
            }
            CloseHandle(hModuleSnap);

            if (moduleBase) {
                // Pattern scan for player position (F3 0F 10 87 ?? ?? ?? ??)
                // This finds: movss xmm0, [rdi + offset]
                const unsigned char playerPosPattern[] = {
                    0xF3, 0x0F, 0x10, 0x87, 0x00, 0x00, 0x00, 0x00
                };
                const char* mask = "xxxx????";

                uintptr_t found = reader.FindPatternEx(
                    playerPosPattern,
                    mask,
                    moduleBase,
                    GameOffsets::PATTERN_SEARCH_SIZE
                );

                if (found) {
                    // Extract player state base from found pattern
                    // At found+4 we have the offset to player position within player structure
                    uintptr_t playerBase = found - GameOffsets::Player::POSITION_X;

                    // Read player position
                    state.position.x = reader.Read<float>(playerBase + GameOffsets::Player::POSITION_X);
                    state.position.y = reader.Read<float>(playerBase + GameOffsets::Player::POSITION_Y);
                    state.classType = reader.Read<int>(playerBase + GameOffsets::Player::CLASS_TYPE);
                    state.level = reader.Read<int>(playerBase + GameOffsets::Player::LEVEL);
                    state.experience = reader.Read<int>(playerBase + GameOffsets::Player::EXPERIENCE);

                    return state;
                }
            }
        }
    }
    catch (...) {
        // Fallback to mock data on error
    }

    // Return mock data as fallback
    static int mockX = 100;
    static int mockY = 200;

    state.position.x = (float)mockX;
    state.position.y = (float)mockY;
    state.classType = 0;
    state.level = 1;
    state.experience = 0;

    return state;
}

