std::vector<MobInfo> BotEngine::GetNearbyMobs(float radius) const
{
    std::vector<MobInfo> mobs;
    if (!m_processHandle)
        return mobs;

    try {
        MemoryReader reader(m_processHandle);
        PlayerState player = GetPlayerState();

        if (player.position.x == 0 && player.position.y == 0)
            return mobs;

        // Get D2R module base
        MODULEENTRY32 me32 = { sizeof(MODULEENTRY32) };
        HANDLE hModuleSnap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE, m_processId);
        if (hModuleSnap != INVALID_HANDLE_VALUE) {
            uintptr_t moduleBase = 0;

            if (Module32First(hModuleSnap, &me32)) {
                do {
                    if (_wcsicmp(me32.szModule, L"D2R.exe") == 0) {
                        moduleBase = (uintptr_t)me32.modBaseAddr;
                        break;
                    }
                } while (Module32Next(hModuleSnap, &me32));
            }
            CloseHandle(hModuleSnap);

            if (moduleBase) {
                // Pattern scan for mob list (48 8B 41 30 - mov rax, [rcx + 0x30])
                const unsigned char mobListPattern[] = {
                    0x48, 0x8B, 0x41, 0x30
                };
                const char* mask = "xxxx";

                uintptr_t found = reader.FindPatternEx(
                    mobListPattern,
                    mask,
                    moduleBase,
                    GameOffsets::PATTERN_SEARCH_SIZE
                );

                if (found) {
                    // Read mob list head pointer
                    uintptr_t mobListHead = reader.Read<uintptr_t>(found);

                    // Iterate through mob list (max 100 mobs to avoid infinite loops)
                    int mobCount = 0;
                    uintptr_t currentMob = mobListHead;

                    while (currentMob && mobCount < 100) {
                        // Read mob structure
                        Vector2D mobPos;
                        mobPos.x = reader.Read<float>(currentMob + GameOffsets::Mob::POSITION_X);
                        mobPos.y = reader.Read<float>(currentMob + GameOffsets::Mob::POSITION_Y);

                        int life = reader.Read<int>(currentMob + GameOffsets::Mob::LIFE);
                        int maxLife = reader.Read<int>(currentMob + GameOffsets::Mob::MAX_LIFE);
                        bool isAlive = life > 0;

                        // Calculate distance
                        float dx = mobPos.x - player.position.x;
                        float dy = mobPos.y - player.position.y;
                        float distance = sqrt(dx * dx + dy * dy);

                        // Add if within radius
                        if (distance <= radius && isAlive) {
                            MobInfo mob;
                            mob.position = mobPos;
                            mob.uniqueId = reader.Read<int>(currentMob + GameOffsets::Mob::UNIQUE_ID);
                            mob.isAlive = isAlive;
                            mob.experience = 10; // Placeholder
                            mobs.push_back(mob);
                        }

                        // Move to next mob
                        currentMob = reader.Read<uintptr_t>(currentMob + GameOffsets::Mob::NEXT_MOB);
                        mobCount++;
                    }
                }
            }
        }
    }
    catch (...) {
        // Return empty on error
    }

    return mobs;
}

